#!/usr/bin/env bun
/**
 * publish-from-dist.mjs
 *
 * Publishes every workspace package from its dist/ subdirectory.
 * dist/package.json is generated by prepare-package-dist.mjs at build time
 * and contains:
 *   - main / types / exports pointing at compiled outputs
 *   - workspace:* deps rewritten to real semver
 *
 * Lerna's default behavior publishes from the package root, which sees the
 * source-of-truth package.json (workspace:* + src/ pointers). This script
 * replaces that step.
 *
 * Usage:
 *   bun packages/scripts/publish-from-dist.mjs             # dry-run
 *   bun packages/scripts/publish-from-dist.mjs --apply     # actual publish
 *   bun packages/scripts/publish-from-dist.mjs --apply --tag beta
 *   bun packages/scripts/publish-from-dist.mjs --apply --filter @elizaos/core,@elizaos/shared
 *   bun packages/scripts/publish-from-dist.mjs --apply --otp 123456
 */

import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { listPackages } from "./lib/workspaces.mjs";
import { assertPublishableWorkspaceGraph } from "./verify-publish-graph.mjs";

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../..");

function npmInvocation(args) {
  if (process.platform === "win32") {
    const npmCliPath = join(
      dirname(process.execPath),
      "node_modules",
      "npm",
      "bin",
      "npm-cli.js",
    );
    if (existsSync(npmCliPath)) {
      return { command: process.execPath, args: [npmCliPath, ...args] };
    }
  }
  return { command: "npm", args };
}

export function parseArgs(argv = process.argv.slice(2)) {
  const flags = {
    apply: argv.includes("--apply"),
    tag: undefined,
    filter: undefined,
    otp: undefined,
  };
  const tagIdx = argv.indexOf("--tag");
  if (tagIdx >= 0) flags.tag = argv[tagIdx + 1];
  const filterIdx = argv.indexOf("--filter");
  if (filterIdx >= 0)
    flags.filter = argv[filterIdx + 1].split(",").map((s) => s.trim());
  const otpIdx = argv.indexOf("--otp");
  if (otpIdx >= 0) flags.otp = argv[otpIdx + 1];
  return flags;
}

export function main(options = {}) {
  const flags = options.flags ?? parseArgs();
  const workspacePackages = assertPublishableWorkspaceGraph(
    options.packages ?? listPackages(),
  );
  const pkgs = workspacePackages
    .filter((pkg) => pkg.packageJson?.name && pkg.packageJson.private !== true)
    .map((pkg) => ({
      name: pkg.packageJson.name,
      dir: resolve(REPO_ROOT, pkg.dir),
      version: pkg.packageJson.version,
    }));
  const filtered = flags.filter
    ? pkgs.filter((p) => flags.filter.includes(p.name))
    : pkgs;

  console.log(
    `${flags.apply ? "[PUBLISH]" : "[DRY-RUN]"} ${filtered.length} packages`,
  );
  if (flags.tag) console.log(`  tag: ${flags.tag}`);
  if (flags.filter) console.log(`  filter: ${flags.filter.join(", ")}`);

  let succeeded = 0;
  let failed = 0;
  for (const pkg of filtered) {
    const distDir = join(pkg.dir, "dist");
    if (!existsSync(join(distDir, "package.json"))) {
      console.warn(
        `  ${pkg.name}: SKIP (no dist/package.json — did you run build?)`,
      );
      continue;
    }
    const args = [flags.apply ? "publish" : "pack", "--dry-run"];
    if (flags.apply) args.splice(1, 1); // remove --dry-run for real publish
    if (flags.tag) args.push("--tag", flags.tag);
    if (flags.otp) args.push("--otp", flags.otp);
    args.push("--access", "public");

    try {
      console.log(`  ${pkg.name}@${pkg.version}: ${args.join(" ")}`);
      const npm = npmInvocation(args);
      execFileSync(npm.command, npm.args, { cwd: distDir, stdio: "inherit" });
      succeeded++;
    } catch (err) {
      failed++;
      console.error(`    FAILED: ${err.message}`);
    }
  }

  console.log(`\nDone. ${succeeded} succeeded, ${failed} failed.`);
  if (failed) process.exit(1);
  return { succeeded, failed };
}

const invokedDirectly =
  import.meta.main ||
  (Boolean(process.argv[1]) &&
    resolve(process.argv[1]) === fileURLToPath(import.meta.url));

if (invokedDirectly) {
  try {
    main();
  } catch (error) {
    console.error(error instanceof Error ? error.message : error);
    process.exitCode = 1;
  }
}
